#!/usr/bin/env python3
"""Write assets/credits/environment.json from the build records.

    python3 -I tools/env/build_credits.py

One entry per *source* asset (a Sketchfab model, a Poly Haven model/texture/
HDRI, an ambientCG material) listing every file we ship that was derived from
it, plus an entry for original procedural work (the water normal map).
Inputs:
  tools/env/env_recipes.json             which game asset came from which source
  tools/_cache/env/_build/<id>.json      what process_models.py did to it ("changes")
  tools/_cache/env/{ph,sf,acg}_*/        API metadata saved at download time
  tools/env/build_textures.py            terrain layer / HDRI mapping (imported)
"""
from __future__ import annotations

import ast
import importlib.util
import json
import urllib.parse
from collections import OrderedDict
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ROOT = TOOLS.parents[1]
CACHE = ROOT / "tools" / "_cache" / "env"
BUILD = CACHE / "_build"
OUT = ROOT / "assets" / "credits" / "environment.json"

CC0 = ("CC0 1.0", "https://creativecommons.org/publicdomain/zero/1.0/")


def load_build_textures():
    spec = importlib.util.spec_from_file_location("build_textures", TOOLS / "build_textures.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def polyhaven_entry(asset_id: str, kind: str) -> dict:
    info = json.loads((CACHE / f"ph_{asset_id}" / "info.json").read_text())
    authors = list(info.get("authors", {}).keys())
    return {
        "asset": f"{info['name']} (Poly Haven {kind})",
        "author": ", ".join(authors),
        "author_url": "https://polyhaven.com/all?a=" + urllib.parse.quote(authors[0]) if authors else "https://polyhaven.com",
        "source_url": f"https://polyhaven.com/a/{asset_id}",
        "license": CC0[0],
        "license_url": CC0[1],
    }


def sketchfab_entry(uid: str) -> dict:
    meta = json.loads((CACHE / f"sf_{uid}" / "meta.json").read_text())
    return {
        "asset": meta["name"],
        "author": meta["author"],
        "author_url": meta["author_url"],
        "source_url": meta["source_url"],
        "license": meta["license"],
        "license_url": meta["license_url"],
    }


def ambientcg_entry(asset_id: str) -> dict:
    info = json.loads((CACHE / f"acg_{asset_id}" / "info.json").read_text())
    return {
        "asset": f"{info.get('displayName', asset_id)} (ambientCG material {asset_id})",
        "author": "Lennart Demes (ambientCG)",
        "author_url": "https://ambientcg.com/",
        "source_url": f"https://ambientcg.com/view?id={asset_id}",
        "license": CC0[0],
        "license_url": CC0[1],
    }


def generated_entries(module: str, recipes: list[dict]) -> list[dict]:
    """Procedural mesh = original project work; its textures keep their own CC0 credit."""
    # the generator declares SOURCES = {"textures": [...]}; read it with ast so that
    # bpy (only available inside Blender) is never imported here
    tree = ast.parse((TOOLS / f"{module}.py").read_text())
    tex_ids = []
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(getattr(t, "id", "") == "SOURCES" for t in node.targets):
            tex_ids = ast.literal_eval(node.value).get("textures", [])
    files = [f"assets/env/{r['id']}/{r['id']}.glb" for r in recipes]
    used = ", ".join(f"{r.get('desc', r['id'])} ({r['id']})" for r in recipes)
    out = [{
        "asset": f"{used.split(' (')[0].capitalize()} (procedural mesh)",
        "author": "Bunny Beat Down project",
        "author_url": "",
        "source_url": f"tools/env/{module}.py",
        "license": "MIT (project)",
        "license_url": "https://opensource.org/licenses/MIT",
        "changes": "Original work: mesh generated by a Blender script; textures credited separately",
        "used_for": "Environment scenery: " + used,
        "files": files,
    }]
    for t in tex_ids:
        e = polyhaven_entry(t, "texture")
        e["changes"] = "Re-encoded to 1024px (JPEG colour, PNG normal, packed AO/roughness JPEG) and embedded in the GLB"
        e["used_for"] = "Surface material of " + used
        e["files"] = list(files)
        out.append(e)
    return out


def merge_by_source(entries: list[dict]) -> list[dict]:
    """One credits entry per source URL even if it is used in several places."""
    merged: "OrderedDict[str, dict]" = OrderedDict()
    for e in entries:
        key = e["source_url"]
        if key not in merged:
            merged[key] = dict(e)
            continue
        m = merged[key]
        m["files"] = m["files"] + [f for f in e["files"] if f not in m["files"]]
        m["used_for"] = m["used_for"] + "; " + e["used_for"]
        m["changes"] = m["changes"] + " | " + e["changes"]
    return list(merged.values())


def model_entries() -> list[dict]:
    recipes = json.loads((TOOLS / "env_recipes.json").read_text())["assets"]
    manifest = {e["id"] for e in json.loads((ROOT / "assets" / "env" / "manifest.json").read_text())}
    by_source: "OrderedDict[str, list[dict]]" = OrderedDict()
    for r in recipes:
        if r["id"] in manifest:
            by_source.setdefault(r["source"], []).append(r)
    entries = []
    for source, rs in by_source.items():
        kind, ident = source.split(":", 1)
        if kind == "gen":
            entries.extend(generated_entries(ident, rs))
            continue
        e = polyhaven_entry(ident, "model") if kind == "ph" else sketchfab_entry(ident)
        changes, used, files = [], [], []
        for r in rs:
            build = json.loads((BUILD / f"{r['id']}.json").read_text())
            changes.append(f"{r['id']}: " + "; ".join(build["changes"]))
            used.append(f"{r.get('desc', r['id'])} ({r['id']})")
            files.append(f"assets/env/{r['id']}/{r['id']}.glb")
        e["changes"] = " | ".join(changes) + " | exported as GLB (+Y up, metres)"
        e["used_for"] = "Environment scenery: " + ", ".join(used)
        e["files"] = files
        entries.append(e)
        # materials swapped for a Poly Haven surface (e.g. sharper tree bark) credit that texture too
        for r in rs:
            for mat, spec in r.get("retexture", {}).items():
                t = polyhaven_entry(spec["ph"], "texture")
                t["changes"] = (f"Resampled to {spec['size'][0]}x{spec['size'][1]} (normal "
                                f"{spec.get('normal_size', spec['size'])[0]}x{spec.get('normal_size', spec['size'])[1]}) "
                                "to fit the model's bark UV layout; AO/roughness packed into one JPEG")
                t["used_for"] = f"Bark material of {r.get('desc', r['id'])} ({r['id']})"
                t["files"] = [f"assets/env/{r['id']}/{r['id']}.glb"]
                entries.append(t)
    return entries


def texture_entries() -> list[dict]:
    bt = load_build_textures()
    entries = []
    for layer, (folder, size, desc) in bt.LAYERS.items():
        kind, ident = folder.split("_", 1)
        e = polyhaven_entry(ident, "texture") if kind == "ph" else ambientcg_entry(ident)
        files = sorted(str(p.relative_to(ROOT)) for p in (ROOT / "assets" / "textures" / layer).glob("*")
                       if p.suffix != ".import")
        e["changes"] = (f"Downscaled to {size}px (AO/height 1024px), normal map converted to 8-bit PNG "
                        "(OpenGL convention), greyscale maps re-encoded as JPEG")
        e["used_for"] = f"Terrain texture layer '{layer}' ({desc})"
        e["files"] = files
        entries.append(e)
    for h in bt.HDRIS:
        e = polyhaven_entry(h, "HDRI")
        files = sorted(str(p.relative_to(ROOT)) for p in (ROOT / "assets" / "sky").glob(f"{h}_*.hdr"))
        e["changes"] = "None (original 2K" + (" and 4K" if any("_4k" in f for f in files) else "") + " .hdr files)"
        e["used_for"] = "Sky / image-based lighting" + (" (default sunny sky)" if h == bt.HDRIS[0] else " (soft afternoon sky)")
        e["files"] = files
        entries.append(e)
    entries.append({
        "asset": "Water ripple normal map",
        "author": "Bunny Beat Down project",
        "author_url": "",
        "source_url": "tools/env/build_textures.py",
        "license": "MIT (project)",
        "license_url": "https://opensource.org/licenses/MIT",
        "changes": "Original work, generated procedurally (sum of tileable ripples)",
        "used_for": "Pond / sea surface normal map",
        "files": ["assets/textures/water/normal.png"],
    })
    return entries


def main() -> None:
    entries = merge_by_source(model_entries() + texture_entries())
    # sanity: every license must be one the project allows
    allowed = {"CC0 1.0", "CC BY 4.0", "CC BY 3.0", "MIT (project)"}
    bad = [e["asset"] for e in entries if e["license"] not in allowed]
    if bad:
        raise SystemExit(f"disallowed licenses: {bad}")
    for e in entries:
        for f in e["files"]:
            if not (ROOT / f).exists():
                raise SystemExit(f"credited file missing: {f}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(entries, indent=2, ensure_ascii=False) + "\n")
    print(f"wrote {OUT.relative_to(ROOT)}: {len(entries)} entries")


if __name__ == "__main__":
    main()
